mapper.select:
SELECT t.*, u.real_name AS seller_name, c.course_name, m.major_name
FROM textbook t
LEFT JOIN sys_user u ON t.seller_id = u.id
LEFT JOIN sys_course c ON t.course_id = c.id
LEFT JOIN sys_major m ON t.major_id = m.id
WHERE t.deleted = 0

    AND (t.title LIKE CONCAT('%',#{keyword},'%') OR t.author LIKE CONCAT('%',#{keyword},'%') OR t.publisher LIKE CONCAT('%',#{keyword},'%'))

AND t.course_id = #{courseId}
AND t.major_id = #{majorId}
AND t.grade = #{grade}
AND t.book_condition = #{condition}
AND t.price >= #{minPrice}
AND t.price <= #{maxPrice}
AND t.status = #{status}
AND t.status = 'ON_SALE'
AND t.seller_id = #{sellerId}

    ORDER BY t.price ASC
    ORDER BY t.price DESC
    ORDER BY t.view_count DESC
    ORDER BY t.create_time DESC
